import java.text.DecimalFormat;
import java.util.Scanner;
import java.util.Random;

public class DiceProbabilitySimulator {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        Random rand = new Random();
        DecimalFormat df = new DecimalFormat("#.####");

        // Theoretical probabilities based on dice combinations
        // 2:1, 3:2, 4:3, 5:4, 6:5, 7:6, 8:5, 9:4, 10:3, 11:2, 12:1
        int[] theoreticalCounts = {0, 0, 1, 2, 3, 4, 5, 6, 5, 4, 3, 2, 1};
        double[] theoreticalProbs = new double[13];
        for (int i = 2; i <= 12; i++) {
            theoreticalProbs[i] = (double) theoreticalCounts[i] / 36.0;
        }

        // Display theoretical probability distribution
        System.out.println("Theoretical Probability Distribution");
        System.out.println("X\tP(X)");
        System.out.println("-------------------");
        for (int x = 2; x <= 12; x++) {
            System.out.println(x + "\t" + df.format(theoreticalProbs[x]));
        }

        // User interaction for number of simulations
        System.out.print("\nEnter the number of simulations to run: ");
        int numSimulations = scanner.nextInt();
        int[] simulations = new int[numSimulations];

        // User interaction for number of rolls per simulation
        for (int i = 0; i < numSimulations; i++) {
            System.out.print("Enter number of rolls for simulation " + (i + 1) + " (e.g., 36, 500, 10000): ");
            simulations[i] = scanner.nextInt();
        }

        // Run and display results for each simulation
        for (int numRolls : simulations) {
            int[] counts = new int[13];

            // Simulate rolling two dice numRolls times
            for (int i = 0; i < numRolls; i++) {
                int die1 = 1 + rand.nextInt(6);
                int die2 = 1 + rand.nextInt(6);
                int sum = die1 + die2;
                counts[sum]++;
            }

            // Display simulation results in table format
            System.out.println("\nSimulation of " + numRolls + " rolls:");
            System.out.println("X\tCount\tEm Prob\tP(X)");
            System.out.println("--------------------------------------------------");

            for (int x = 2; x <= 12; x++) {
                double empiricalProb = (double) counts[x] / numRolls;

                // Format X and Count
                System.out.print(x + "\t" + counts[x]);

                // Adjust tabs after Count based on its length
                if (counts[x] < 10) {
                    System.out.print("\t\t\t"); // 3 tabs for single-digit counts
                } else if (counts[x] < 100) {
                    System.out.print("\t\t"); // 2 tabs for 2-digit counts
                } else if (counts[x] < 1000) {
                    System.out.print("\t"); // 1 tab for 3-digit counts
                } else {
                    System.out.print("\t"); // 1 tab for larger counts
                }

                // Print probabilities
                System.out.print(df.format(empiricalProb) + "\t" + df.format(theoreticalProbs[x]) + "\n");
            }
        }

        scanner.close();
    }
}

### Understanding PNG Compression Level and Optimization Strategies

#### Impact of Compression Level on PNG Size
PNG uses **DEFLATE compression**, a lossless algorithm that balances file size and CPU usage. The `ZLibLevel` parameter (0–9) in SkiaSharp controls this compression:
- **Level 0**: No compression (largest file size, fastest processing).
- **Level 1–9**: Increasing compression effort. Level 6 is often the **optimal balance** between size and performance.
- Higher levels reduce file size but with diminishing returns (e.g., level 9 may only save 5–10% over level 6).

#### Key Optimization Techniques for PNG
1. **Adjust Compression Level**
   Use `ZLibLevel=6` as a default for most use cases.

2. **Reduce Color Depth**
   - Convert to **grayscale** if no color is needed.
   - Use indexed color with a limited palette (e.g., 256 colors).

3. **Remove Metadata**
   Strip unnecessary chunks (e.g., EXIF, comments) during save.

4. **Resize Responsibly**
   Downscale images to the required display size.

---

### C# Code Example Using SkiaSharp

```csharp
using SkiaSharp;

public static byte[] ConvertImageToByteArray(
    string imagePath, 
    string format = "png", 
    int quality = 80, 
    int compressionLevel = 6, 
    (int width, int height)? resize = null)
{
    // Load the image
    using var bitmap = SKBitmap.Decode(imagePath);

    // Resize if needed
    SKImage resizedImage = null;
    if (resize.HasValue)
    {
        var targetSize = resize.Value;
        using var surface = new SKCanvas(new SKImageInfo(targetSize.width, targetSize.height));
        var image = SKImage.FromBitmap(bitmap);
        surface.Scale((float)targetSize.width / bitmap.Width, (float)targetSize.height);
        surface.DrawImage(image, 0, 0);
        resizedImage = surface.Snapshot();
    }

    // Use resized image if available, otherwise original
    using var sourceImage = resizedImage ?? SKImage.FromBitmap(bitmap);

    // Determine output format
    SKEncodedImageFormat imageFormat;
    if (format.ToLower() == "png")
    {
        imageFormat = SKEncodedImageFormat.Png;
    }
    else if (format.ToLower() == "jpeg")
    {
        imageFormat = SKEncodedImageFormat.Jpeg;
    }
    else
    {
        throw new ArgumentException("Unsupported format. Use 'png' or 'jpeg'.");
    }

    // Create encoder options
    SKEncoderOptions options;
    if (imageFormat == SKEncodedImageFormat.Png)
    {
        options = new SKPngEncoderOptions
        {
            ZLibLevel = compressionLevel // 0-9, 6 is default
        };
    }
    else
    {
        options = new SKJpegEncoderOptions
        {
            Quality = quality // 0-100
        };
    }

    // Encode and return byte array
    using var encodedData = sourceImage.Encode(options);
    return encodedData.ToArray();
}
```

---

### Detailed Guidance

#### 1. **Compression Level Tradeoffs**
```csharp
public static void CompareCompressionLevels(string imagePath)
{
    for (int level = 0; level <= 9; level++)
    {
        var result = ConvertImageToByteArray(imagePath, "png", compressionLevel: level);
        Console.WriteLine($"Level {level}: {result.Length / 1024.0:F2} KB");
    }
}
```

#### 2. **Color Reduction for Smaller Sizes**
SkiaSharp supports color space conversion:
```csharp
using var grayscale = bitmap.ToColorSpace(SKColorSpace.CreateGrayscale(), SKColorType.Gray8, SKColorAlphaType.Opaque);
```

For indexed color support, you may need to use additional libraries like **ImageSharp** or **System.Drawing**.

#### 3. **Metadata Removal**
SkiaSharp does not preserve metadata during encoding, so this is handled implicitly.

---

### Summary of Recommendations
| Optimization | File Size Impact | Notes |
|--------------|------------------|-------|
| `ZLibLevel=6` | ✅ 30–50% smaller than level 0 | Default for most cases |
| Grayscale conversion | ✅ 30–70% smaller (for grayscale content) | Use for black-and-white images |
| Palette reduction | ✅ 20–40% smaller | Requires external tools or libraries |
| Metadata removal | ✅ 1–5% smaller | Handled automatically by SkiaSharp |
| Resize to display size | ✅ Up to 80% smaller | Use `SKCanvas.Scale()` for quality resizing |

Use these techniques in combination for maximum savings.

