const { workerData } = require('worker_threads');
const papaparse = require('papaparse');
const fs = require('fs');
const { Client } = require('pg');
const nodemailer = require('nodemailer');
const path = require('path');
const Redis = require('ioredis');
const { v4: uuidv4 } = require('uuid');

// Redis connection for progress tracking
const redis = new Redis();

// Worker data destructuring
const [jobId, csvPath, dbConfig, admin, chunkIndex, chunkCount] = workerData;
const client = new Client(JSON.parse(dbConfig));
const batchSize = 500;

// Create email transporter
const transporter = nodemailer.createTransport({
    host: process.env.SMTP_HOST,
    port: process.env.SMTP_PORT,
    auth: {
        user: process.env.SMTP_USER,
        pass: process.env.SMTP_PASS
    }
});

// Email notification function
const sendNotification = async (success, error = null) => {
    const message = {
        from: 'no-reply@company.com',
        to: admin,
        subject: success ? 'Import Success' : 'Import Failed',
        text: success 
            ? 'Customer data has been successfully imported' 
            : `Import error: ${error}`
    };

    try {
        await transporter.sendMail(message);
    } catch (err) {
        console.error('Email notification failed:', err);
    }
};

// Batch insert function
const insertBatch = async (batch) => {
    if (batch.length === 0) return;

    const columns = Object.keys(batch[0]).join(', ');
    const values = batch.map((row, i) => 
        `(${Object.values(row).map((_, j) => 
            `$${i * Object.keys(row).length + j + 1}`
        ).join(', ')})`
    ).join(', ');

    const flatValues = batch.flatMap(Object.values);

    try {
        await client.query(`INSERT INTO customers (${columns}) VALUES ${values}`, flatValues);
    } catch (err) {
        throw err;
    }
};

// Update job progress
const updateProgress = async (progress, message = '') => {
    const jobData = await redis.hgetall(`import:${jobId}`);
    if (!jobData) return;

    const status = JSON.parse(jobData.status);
    status.progress = progress;
    status.lastMessage = message;
    status.lastUpdated = new Date().toISOString();

    await redis.hset(`import:${jobId}`, 'status', JSON.stringify(status));
};

// Main processing function
const processCSV = async () => {
    try {
        await client.connect();

        const stream = fs.createReadStream(csvPath);
        const batch = [];
        let recordCount = 0;
        let processedCount = 0;

        // Count total records first (optional)
        // This would be better done with a separate stream
        // For simplicity, we'll update progress based on processed records

        papaparse.parse(stream, {
            header: true,
            skipEmptyLines: true,
            step: async (results, parser) => {
                // Distribute rows across workers
                if (recordCount % chunkCount === parseInt(chunkIndex)) {
                    batch.push(results.data);

                    if (batch.length >= batchSize) {
                        await insertBatch(batch);
                        processedCount += batch.length;
                        batch = [];

                        // Update progress every 1000 records
                        if (processedCount % 1000 === 0) {
                            updateProgress(
                                Math.min(90, Math.floor(processedCount / 1000)), 
                                `Processed ${processedCount} records`
                            );
                        }
                    }
                }
                recordCount++;
            },
            complete: async () => {
                if (batch.length > 0) {
                    await insertBatch(batch);
                    processedCount += batch.length;
                }

                // Mark this worker as complete
                const jobData = await redis.hgetall(`import:${jobId}`);
                if (!jobData) return;

                const status = JSON.parse(jobData.status);
                status[`worker_${chunkIndex}`] = 'complete';

                // Check if all workers are complete
                let allComplete = true;
                for (let i = 0; i < chunkCount; i++) {
                    if (!status[`worker_${i}`]) {
                        allComplete = false;
                        break;
                    }
                }

                if (allComplete) {
                    await updateProgress(100, 'Import completed successfully');
                    await sendNotification(true);
                }

                await client.end();
            },
            error: async (err) => {
                await updateProgress(0, `Error: ${err.message}`);
                await sendNotification(false, err.message);
                await client.end();
            }
        });

    } catch (err) {
        await updateProgress(0, `Error: ${err.message}`);
        await sendNotification(false, err.message);
        await client.end();
    }
};

processCSV();
