/**
 * @brief Izhikevich Neuron Class for Simulating Primitive Animal Nervous Systems
 * 
 * This class implements the Izhikevich neuron model with support for dynamic
 * connectivity and synaptic plasticity. It's designed to simulate the nervous
 * system of primitive animals with features like:
 * - Different neuron types (regular spiking, fast spiking, bursting)
 * - Synaptic plasticity (STDP) for basic learning
 * - Dynamic connection/disconnection for development/injury modeling
 * - Efficient memory usage for large-scale networks
 */
class IzhikevichNeuron {
public:
    // Neuron types inspired by primitive animal nervous system diversity
    enum class NeuronType { RegularSpiking, FastSpiking, Bursting, Inhibitory };

    /**
     * @brief Construct a new Izhikevich Neuron object
     * 
     * @param type Type of neuron (determines default parameters)
     * @param id Unique identifier for the neuron in the network
     */
    IzhikevichNeuron(NeuronType type, int id) : neuronId(id), lastSpikeTime(-1e6) {
        setNeuronType(type);
        reset();
    }

    // Core simulation methods
    void integrate(float dt, float externalInput);
    bool checkAndResetSpike();
    void addInputConnection(int preNeuronId, float weight, float delay = 0.0f);
    void removeInputConnection(int preNeuronId);
    void updatePlasticity(float currentTime);

    // Helper methods for network management
    void sendSpike(std::vector<std::pair<float, int>>& spikeQueue) const;

    // Getters and setters
    float getMembranePotential() const { return v; }
    int getId() const { return neuronId; }
    NeuronType getType() const { return neuronType; }

    // Static methods for network-wide operations
    static void propagateSpikes(const std::vector<std::pair<float, int>>& spikeQueue,
                                std::vector<IzhikevichNeuron>& allNeurons, float currentTime);

private:
    // Neuron state variables
    float v; // Membrane potential
    float u; // Recovery variable
    bool spikeState;

    // Izhikevich parameters
    float a, b, c, d;

    // Synaptic properties
    std::unordered_map<int, float> inputWeights; // Connected input neuron IDs and their weights
    std::unordered_map<int, float> inputDelays;   // Delays for input connections

    // Plasticity parameters
    static constexpr float tauSTDP = 20.0f; // STDP time window
    static constexpr float minWeight = 0.1f;
    static constexpr float maxWeight = 2.0f;
    float lastSpikeTime;

    // Neuron identity
    int neuronId;
    NeuronType neuronType;

    // Helper methods
    void reset() {
        v = -70.0f; // Resting potential
        u = b * v;  // Initial recovery variable
        spikeState = false;
    }

    void setNeuronType(NeuronType type) {
        neuronType = type;
        switch (type) {
            case NeuronType::RegularSpiking:
                a = 0.02f; b = 0.2f; c = -65.0f; d = 8.0f;
                break;
            case NeuronType::FastSpiking:
                a = 0.1f; b = 0.2f; c = -65.0f; d = 2.0f;
                break;
            case NeuronType::Bursting:
                a = 0.02f; b = 0.25f; c = -55.0f; d = 4.0f;
                break;
            case NeuronType::Inhibitory:
                a = 0.02f; b = 0.25f; c = -65.0f; d = 2.0f;
                break;
        }
    }
};

// Implementation of methods
void IzhikevichNeuron::integrate(float dt, float externalInput) {
    // Izhikevich model equations
    float dv = (0.04f * v*v + 5.0f * v + 140.0f - u + externalInput) * dt;
    v += dv;

    float du = (a * (b * v - u)) * dt;
    u += du;
}

bool IzhikevichNeuron::checkAndResetSpike() {
    bool result = spikeState;
    spikeState = false; // Reset spike state
    if (v >= 30.0f) { // Spike threshold
        v = c; // Reset membrane potential
        u += d; // Update recovery variable
        spikeState = true;
        lastSpikeTime = getMembranePotential(); // Store spike time for STDP
    }
    return result;
}

void IzhikevichNeuron::addInputConnection(int preNeuronId, float weight, float delay) {
    inputWeights[preNeuronId] = weight;
    inputDelays[preNeuronId] = delay;
}

void IzhikevichNeuron::removeInputConnection(int preNeuronId) {
    inputWeights.erase(preNeuronId);
    inputDelays.erase(preNeuronId);
}

void IzhikevichNeuron::updatePlasticity(float currentTime) {
    // STDP implementation - Spike Timing Dependent Plasticity
    // Adjusts synaptic weights based on relative timing of pre and post spikes
    for (auto& [preId, weight] : inputWeights) {
        float deltaT = currentTime - lastSpikeTime;

        // Basic STDP rule: pre before post potentiates, post before pre depresses
        if (deltaT > 0 && deltaT < tauSTDP) { // LTP
            weight = std::min(maxWeight, weight + 0.1f * (1.0f - weight));
        } else if (deltaT < 0 && deltaT > -tauSTDP) { // LTD
            weight = std::max(minWeight, weight - 0.1f * weight);
        }
    }
}

void IzhikevichNeuron::sendSpike(std::vector<std::pair<float, int>>& spikeQueue) const {
    if (spikeState) {
        // Add spike to queue with delay (for network propagation)
        for (const auto& [targetId, delay] : inputDelays) {
            spikeQueue.emplace_back(getMembranePotential() + delay, targetId);
        }
    }
}

void IzhikevichNeuron::propagateSpikes(const std::vector<std::pair<float, int>>& spikeQueue,
                                       std::vector<IzhikevichNeuron>& allNeurons, float currentTime) {
    // Apply incoming spikes to target neurons
    for (const auto& [spikeTime, targetId] : spikeQueue) {
        if (targetId >= 0 && targetId < allNeurons.size()) {
            // Find the connection strength
            const auto& neuron = allNeurons[targetId];
            auto it = neuron.inputWeights.find(targetId);
            if (it != neuron.inputWeights.end()) {
                // Add current to the postsynaptic neuron
                float current = it->second * 0.5f; // Simplified synaptic current
                allNeurons[targetId].integrate(0.0f, current); // Apply as external input
            }
        }
    }
}

/**
 * @brief Network class for managing large-scale simulations with optimized memory usage
 * 
 * Features:
 * - Vector-based storage for memory efficiency and cache-friendly access
 * - Sparse connectivity representation
 * - Event-based processing for scalability
 * - Optimized for simulating over 1 million neurons
 */
class NeuralNetwork {
public:
    NeuralNetwork(int numNeurons, float dt = 0.01f) 
        : numNeurons(numNeurons), dt(dt), currentTime(0.0f) {
        if (dt <= 0.0f) {
            throw std::invalid_argument("Time step must be positive");
        }

        // Reserve memory for neurons to avoid reallocations
        neurons.reserve(numNeurons);

        // Initialize neurons with random types
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dist(0, 3);

        for (int i = 0; i < numNeurons; ++i) {
            int type = dist(gen);
            neurons.emplace_back(static_cast<IzhikevichNeuron::NeuronType>(type), i);
        }
    }

    void step(float externalInput = 0.0f) {
        // Input buffer for each neuron
        std::vector<float> inputs(numNeurons, 0.0f);

        // 1. Integrate neuron dynamics
        for (auto& neuron : neurons) {
            inputs[neuron.getId()] += externalInput;
        }

        // 2. Process neuron integration
        for (size_t i = 0; i < neurons.size(); ++i) {
            neurons[i].integrate(dt, inputs[i]);
        }

        // 3. Check for spikes
        std::vector<std::pair<float, int>> spikeQueue;
        for (auto& neuron : neurons) {
            if (neuron.checkAndResetSpike()) {
                spikeQueue.emplace_back(currentTime, neuron.getId());
            }
        }

        // 4. Propagate spikes
        IzhikevichNeuron::propagateSpikes(spikeQueue, neurons, currentTime);

        // 5. Update synaptic plasticity
        for (auto& neuron : neurons) {
            neuron.updatePlasticity(currentTime);
        }

        currentTime += dt;
    }

    void runSimulation(float duration, float inputStrength = 0.0f) {
        int steps = static_cast<int>(duration / dt);

        // Simple input pattern - apply to first 10% of neurons
        int inputNeuronCount = numNeurons / 10;

        for (int i = 0; i < steps; ++i) {
            // Apply input between 200-800ms
            float input = 0.0f;
            if (i * dt > 200.0f && i * dt < 800.0f) {
                input = inputStrength;
            }

            step(input);

            // Progress report
            if (i % (steps / 10) == 0) {
                std::cout << "Simulation progress: " << (i * 100.0f / steps) << "% complete\r";
            }
        }

        std::cout << "\nSimulation completed." << std::endl;
    }

    // Method to dynamically disconnect neurons
    bool disconnectNeurons(int preId, int postId) {
        if (preId < 0 || preId >= numNeurons || postId < 0 || postId >= numNeurons) {
            return false;
        }

        neurons[postId].removeInputConnection(preId);
        return true;
    }

private:
    int numNeurons;
    float dt;
    float currentTime;
    std::vector<IzhikevichNeuron> neurons;
};

// Example usage for primitive animal nervous system simulation
